using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Staff.Subway;
public static class CloudMotionSetup {
 static double probeStart;static Vector2 probeWind;static SubwayTimeOfDay probeSky;
 static void Probe(){if(EditorApplication.timeSinceStartup-probeStart<8)return;EditorApplication.update-=Probe;if(!probeSky)return;var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/VolumetricClouds/VolumetricClouds.mat");var gpu=material.GetVector("_WindVector");var delta=probeSky.CloudDisplacement-probeWind;string report="Editor cloud drift over 8s: "+delta.magnitude+"m; GPU wind="+gpu+"; shared wind="+probeSky.CloudDisplacement;File.WriteAllText("Library/StaffSubway/cloud-motion-live.txt",report);Debug.Log(report);}

 [MenuItem("STAFF/Subway/Fix Cloud Motion and Save Moon")]
 public static void Install(){if(EditorApplication.isPlaying)throw new Exception("Exit Play mode first.");var sky=UnityEngine.Object.FindFirstObjectByType<SubwayTimeOfDay>();if(!sky)throw new Exception("No sky");Directory.CreateDirectory("Library/StaffSubway");EditorSceneManager.SaveScene(sky.gameObject.scene,"Library/StaffSubway/before-cloud-motion.unity",true);Undo.RecordObject(sky,"Fix cloud motion and preserve Moon");sky.skyWeather.animate=true;sky.skyWeather.windMetersPerSecond=12;sky.ApplySky();EditorUtility.SetDirty(sky);EditorSceneManager.MarkSceneDirty(sky.gameObject.scene);EditorSceneManager.SaveScene(sky.gameObject.scene);File.WriteAllText("Library/StaffSubway/authored-moon.json",JsonUtility.ToJson(sky.moon,true));probeSky=sky;probeStart=EditorApplication.timeSinceStartup;probeWind=sky.CloudDisplacement;EditorApplication.update-=Probe;EditorApplication.update+=Probe;Debug.Log("Cloud motion saved: shared weather clock, wind 12 m/s x authored multiplier; current Moon preserved: "+JsonUtility.ToJson(sky.moon));}
}
